export class UIComponent{
  constructor(id,title,type){this.id=id;this.title=title;this.type=type;this.element=null;this.abortController=null;this.boundHandlers=[];this.collapsed=false;}
  render(){const card=document.createElement('article');card.className='widget-card';card.dataset.widgetId=this.id;card.dataset.type=this.type;card.innerHTML=`<header class="widget-header"><div class="widget-title-wrap"><span class="widget-icon" aria-hidden="true">${this.icon()}</span><div><h3>${this.title}</h3><small>${this.subtitle()}</small></div></div><div class="widget-actions"><button class="icon-button collapse-button" type="button" aria-label="Свернуть">⌃</button><button class="icon-button remove-button" type="button" aria-label="Удалить">×</button></div></header><div class="widget-body"></div>`;this.element=card;this.body=card.querySelector('.widget-body');const collapse=card.querySelector('.collapse-button');const remove=card.querySelector('.remove-button');const onCollapse=()=>{this.collapsed=!this.collapsed;card.classList.toggle('is-collapsed',this.collapsed);collapse.textContent=this.collapsed?'⌄':'⌃';collapse.setAttribute('aria-label',this.collapsed?'Развернуть':'Свернуть');this.onChange?.();};const onRemove=()=>this.onRemove?.();collapse.addEventListener('click',onCollapse);remove.addEventListener('click',onRemove);this.boundHandlers.push([collapse,'click',onCollapse],[remove,'click',onRemove]);return card;}
  icon(){return '•'} subtitle(){return ''} destroy(){this.abortController?.abort();for(const [el,event,handler] of this.boundHandlers)el.removeEventListener(event,handler);this.element?.remove();this.element=null;}
}
